B.ao1=new A.lQ("intro_2.jpg",1.05,1.18,B.aV,B.aW,B.Rh)
B.X8=new A.X(B.t,["Ha ha ha ha! Povo de Nova City... a energia do N\xfacleo Nova agora pertence a MIM!","Ha ha ha ha! People of Nova City... the energy of the Nova Core now belongs to ME!","\xa1Ja ja ja ja! Pueblo de Nova City... \xa1la energ\xeda del N\xfacleo Nova ahora me pertenece a M\xcd!"],t.w)
B.anK=new A.ee("emperor",B.X8,"laugh")
B.Xa=new A.X(B.t,["Meus nove chefes v\xe3o guard\xe1-la pelo mundo inteiro. E voc\xeas, heroizinhos... v\xe3o passar uma temporada nas minhas c\xe1psulas!","My nine bosses will guard it all over the world. And you, little heroes... will spend some time in my capsules!","Mis nueve jefes la guardar\xe1n por todo el mundo. Y ustedes, hero\xedtos... \xa1pasar\xe1n una temporada en mis c\xe1psulas!"],t.w)
B.anL=new A.ee("emperor",B.Xa,null)
B.WQ=new A.X(B.t,["Isso \xe9 o que voc\xea pensa!","That's what you think!","\xa1Eso es lo que t\xfa crees!"],t.w)
B.anO=new A.ee("kael",B.WQ,"angry")
B.Ry=s([B.anK,B.anL,B.anO],t.tG)
B.ao2=new A.lQ("intro_3.jpg",1.25,1.05,B.k,B.k,B.Ry)
B.WT=new A.X(B.t,["Num instante, Luna, Mira, Zek e Nex foram levados... e trancados em c\xe1psulas, escondidas nas terras dos nove chefes.","In an instant, Luna, Mira, Zek and Nex were taken... and locked in capsules, hidden in the lands of the nine bosses.","En un instante, Luna, Mira, Zek y Nex fueron llevados... y encerrados en c\xe1psulas, escondidas en las tierras de los nueve jefes."],t.w)
B.anW=new A.ee(null,B.WT,null)
